-- Phase 2 core lore seed: supporting characters, locations, objects, events, claims and relationships.

on conflict (slug) do update set name=excluded.name,entity_type=excluded.entity_type,summary=excluded.summary,state=excluded.state,visibility=excluded.visibility;

on conflict (slug) do update set name=excluded.name,entity_type=excluded.entity_type,summary=excluded.summary,state=excluded.state,visibility=excluded.visibility;

select e.id,'region',e.summary,'{}'::jsonb from public.lore_entities e where e.slug in ('banner-lands','light-heights','east-shoulder','lower-field','duskport','mapless-saddle','stonewater-descent','ash-fields')
on conflict (entity_id) do update set location_kind=excluded.location_kind,public_summary=excluded.public_summary;
select e.id,'settlement',e.summary,'{}'::jsonb from public.lore_entities e where e.slug in ('crown-watch','vey-crossing')
on conflict (entity_id) do update set location_kind=excluded.location_kind,public_summary=excluded.public_summary;
select e.id,'seat',h.id,e.summary,'{}'::jsonb from public.lore_entities e join public.lore_entities h on h.slug='stormrider' where e.slug='the-hub'
on conflict (entity_id) do update set location_kind=excluded.location_kind,associated_house_id=excluded.associated_house_id,public_summary=excluded.public_summary;
select e.id,'institutional_complex',lh.id,wh.id,e.summary,'{}'::jsonb from public.lore_entities e join public.lore_entities lh on lh.slug='light-heights' join public.lore_entities wh on wh.slug='whitehart' where e.slug='bell-of-silence'
on conflict (entity_id) do update set location_kind=excluded.location_kind,parent_location_id=excluded.parent_location_id,associated_house_id=excluded.associated_house_id,public_summary=excluded.public_summary;

select c.id,null,'Road worker; practical, proud, materially minded.','Concrete road/work language; refuses inflated explanations.','Routes, weather, tools, travelers, paid work.','Death is permanent; later stories cannot recover his own voice.',null,'{"source":"Book One Character & Knowledge Map v1.3"}'::jsonb from public.lore_entities c where c.slug='harl'
on conflict (entity_id) do update set personality_core=excluded.personality_core,voice_signature=excluded.voice_signature,pov_observation_bias=excluded.pov_observation_bias,continuity_guardrails=excluded.continuity_guardrails,metadata=excluded.metadata;
select c.id,h.id,'Merchant intelligence grounded in credit, routes, prices, refusal and account keeping.','Practical and transactional without reducing care to cynicism.','Credit, transport, names, contracts, practical leverage.','Do not make her a complete Ravenshade mouthpiece.',null,'{"source":"Book One Character & Knowledge Map v1.3"}'::jsonb from public.lore_entities c join public.lore_entities h on h.slug='ravenshade' where c.slug='nella'
on conflict (entity_id) do update set house_entity_id=excluded.house_entity_id,personality_core=excluded.personality_core,voice_signature=excluded.voice_signature,pov_observation_bias=excluded.pov_observation_bias,continuity_guardrails=excluded.continuity_guardrails,metadata=excluded.metadata;
select c.id,h.id,'Stormrider-linked practical organizer; values roads and reciprocal obligation without formal succession authority.','Direct, work-centered, resistant to being turned into an official messenger.','Roads, group labor, obligations, incompatible reports.','Carries no authoritative Garron truth and no succession authority.',null,'{"source":"Book One Character & Knowledge Map v1.3"}'::jsonb from public.lore_entities c join public.lore_entities h on h.slug='stormrider' where c.slug='roan'
on conflict (entity_id) do update set house_entity_id=excluded.house_entity_id,personality_core=excluded.personality_core,voice_signature=excluded.voice_signature,pov_observation_bias=excluded.pov_observation_bias,continuity_guardrails=excluded.continuity_guardrails,metadata=excluded.metadata;
select c.id,h.id,'Principal Stormrider administrative anchor; capable, patient, materially responsible and tempted to confuse system survival with human survival.','Administrative intimacy rather than exposition; authority carried through work.','Roads, stores, signatures, people waiting, responsibility.','Not a prophetic or dynastic solution; Stormrider must remain morally defensible.',null,'{"source":"Stormrider Civilization File v1.3 / Book Two controls"}'::jsonb from public.lore_entities c join public.lore_entities h on h.slug='stormrider' where c.slug='una'
on conflict (entity_id) do update set house_entity_id=excluded.house_entity_id,personality_core=excluded.personality_core,voice_signature=excluded.voice_signature,pov_observation_bias=excluded.pov_observation_bias,continuity_guardrails=excluded.continuity_guardrails,metadata=excluded.metadata;

select e.id,v.display_name,v.subtitle,v.summary,v.portrait,v.sort_order,'governing','public',v.source_note
from (values
('sela','Sela','The Light Heights','A goatherd whose unfinished Whitehart trial turns her into public meaning she never asked to carry.','sela',10,'Curated spoiler-safe presentation; source: Book One v1.6 / Canon Appendix v1.3.'),
('tomas','Tomas','House Whitehart','The Tester: exact, procedural and increasingly unable to pretend that an unanswered question is the same thing as an empty one.','tomas',20,'Curated spoiler-safe presentation; source: Book One v1.6.'),
('alaine','Mother Alaine','House Whitehart','A senior Whitehart authority whose stillness, intelligence and judgment make her both shelter and danger.','alaine',30,'Curated spoiler-safe presentation; protected family/history disclosures omitted.'),
('fen','Fen','The Light Heights','A worker who knows the names, labor and silences that Whitehart procedure does not know how to hold.','fen',40,'Curated spoiler-safe presentation; source: Book One v1.6.'),
('harl','Harl','The valley','A road worker and guide whose practical judgment matters more to the mountain than anyone’s grand explanation of it.','harl',50,'Curated spoiler-safe presentation; no endpoint disclosed.'),
('perrin','Perrin','House Blackcrest','A Jubilee collector whose attention can feel like kindness even when every useful word may later become a record.','perrin',60,'Curated spoiler-safe presentation; source: Book One v1.6.'),
('ivet','Ivet','House Whitehart','A young novice whose affection is sincere enough to help Sela and sincere enough to make meaning around her.','ivet',70,'Curated spoiler-safe presentation; death and Gate role withheld.'),
('orla','Orla Darun','House Stonebear','A witness for whom standing, wording and obligation remain precise even when precision cannot make an outcome kind.','orla',80,'Curated spoiler-safe presentation.'),
('nella','Nella of Duskport','Duskport trader','A merchant whose credit and moving goods can keep people alive while making every act of help part of a future account.','nella',90,'Curated spoiler-safe presentation.'),
('roan','Roan','The road compacts','A traveler shaped by roads, reciprocal obligation and reports that do not agree with one another.','roan',100,'Curated spoiler-safe presentation; Book Two private relationship withheld.')
) as v(slug,display_name,subtitle,summary,portrait,sort_order,source_note)
join public.lore_entities e on e.slug=v.slug
on conflict (entity_id) do update set display_name=excluded.display_name,subtitle=excluded.subtitle,summary=excluded.summary,portrait_slug=excluded.portrait_slug,sort_order=excluded.sort_order,state=excluded.state,visibility=excluded.visibility,source_note=excluded.source_note;

on conflict (slug) do update set name=excluded.name,entity_type=excluded.entity_type,summary=excluded.summary,state=excluded.state,visibility=excluded.visibility;

select e.id,'book-1',v.first_use,v.custody,v.function,v.end_state,v.spoiler,'{"source":"Book One Object Ledger v1.2; authority bridged to Constitution v1.9"}'::jsonb from public.lore_entities e join (values
('whitehart-ledger','Ch. 5; returns Ch. 46','Whitehart custody; Tomas controls testing entry until Ch. 46, then key passes to Osric.','Turns procedure into standing, inheritance, office, marriage and external recognition.','Sela page blank; Fen unclosed; Osric holds key.','public_safe'),('burned-trial-note','Ch. 1','Tomas writes temporary observation and burns it before judgment.','Preserves doubt from doctrine while preventing later review.','No surviving Sela trial note.','spoiler'),('perrin-commission','Interlude; Ch. 9 arrival','Issued at Crown-watch; carried to Whitehart.','Connects local evidence to Jubilee/Chronicle power.','Commission incomplete/contested in use.','conditional'),('perrin-notebook','Interlude onward; Ch. 34','Perrin records witnesses and later his own selective-report role.','Care, extraction and self-accountability in one object.','Leaves Whitehart with Perrin.','spoiler'),('sela-wire-bound-bowl','Ch. 3 onward','Family object repeatedly taken, returned and reinterpreted.','Ordinary belonging repeatedly turned toward reverence.','Remains behind at Whitehart.','spoiler'),('harls-knife','Ch. 4; Ch. 46–47','Harl → Tam after death → Sela hilt-first before departure.','Practical trust and non-mystical inheritance.','Sela carries east.','spoiler'),('sela-goat-counter','Ch. 37','One old white stone with gray stripe used among nine ration-horizon objects.','Turns childhood counting into political burden.','No cross-book custody significance.','spoiler'),('merta-good-chair','Col/Merta movement','Kept available for Col; later physically used/moved.','Waiting, absence and partial reclamation.','Remains with Merta.','internal'),('col-sleeve-coat','Ch. 6; Ch. 43','Merta preserves clothing; absence and later account gather around it.','Material grief without proof.','Remains with Merta; cannot prove fate.','spoiler'),('east-shoulder-grave-material','Ch. 7 / Ch. 11','Exposed, examined, disputed, reclosed.','Evidence with damaged provenance.','Reclosed; no item proves identity or Eleventh.','conditional'),('bell-shod-beam','Throughout; Ch. 47','Bell has no clapper; human-operated beam is ordinary mechanism.','Institution requires labor to make silence speak.','Final sounding unexplained.','public_safe'),('harls-older-rope','Ch. 16','Tam selects/uses rope based on wet-knot/load behavior.','Practical expertise later simplified into story.','Physical final state secondary; accounts remain contested.','internal'),('wren-field-notes','Ch. 11 onward; Ch. 34 / Ch. 44','Measurements, Jeren sheet, reconstructions, divided report and source key.','Makes method and limits visible.','Working material; not authoritative Chronicle truth.','spoiler'),('duskport-credit-papers','Ch. 19 onward','Nella authorizes timber, fittings, carts, food and later grain through open accounts.','Aid, debt, verification and future leverage.','Obligations survive grain arrival.','conditional'),('iron-fittings-water-line','Ch. 21 onward','Halvard and workers build/correct system; Fen holds overlooked route knowledge.','Infrastructure saves lives and centralizes access/maintenance.','System remains as settlement spine.','conditional'),('signe-bright-cord','Ch. 25','Planning cord becomes lines, pegs and built behavior.','Future planning precedes full consent.','Plan persists beyond cord.','internal'),('permanent-pegs','Ch. 25 onward','Placed before full lawful settlement authority; people move in response.','Temporary guidance becomes land/political fact.','Remain contested evidence.','internal'),('nine-ration-day-objects','Ch. 37','Button, bent nail, two cherry stones, copper mark, sheep tooth, black game piece, harness ring, goat counter.','Makes scarcity bodily and hard to abstract.','Used to frame closure horizon.','spoiler'),('gate-leaves-hinges-bar','Ch. 39–44','Open inward; closure, crowd pressure and later measurement reveal architecture’s role.','Material geometry defeats abstract intention.','Damaged but extant; inward opening preserved.','public_safe'),('treatment-sheets-wrist-tags','Ch. 41–44','Maren records bodies and physical marks; Fen/Wren later compare records.','Medicine, identity, burial, privacy and future use share one record.','Nine body records remain distinct from twelve missing.','spoiler'),('ivet-wrist-tag','Ch. 42–43','Maren writes Ivet’s name after Sela identifies her.','Refuses anonymous reduction without making martyrdom.','Burial record, not metaphysical claim.','spoiler'),('joric-shield-spear','Ch. 30','Joric uses borrowed store shield and retainer spear to hold wound lane.','Violence reveals reversal through action, not absolution.','Joric dies; custody not cross-book critical.','spoiler'),('nella-grain-carts','Ch. 44–45','Purchased/staged before closure, delayed by road.','Prevents deus-ex-machina relief while creating debt and political fact.','Grain distributed; contracts remain.','spoiler'),('halla-grain-ticket','Ch. 45','Nella enters name with explicit future refusal/record terms.','Protection, debt, literacy and future power.','Halla keeps ticket.','spoiler'),('corrin-staff','Ch. 45','Broken during Tam’s assault.','Physical violence alters singer, song and memory transmission.','Broken; Corrin survives with lasting voice/jaw consequence.','spoiler'),('false-quotation-copies','Ch. 45–46','False line circulates in several hands.','Words detach from original speaker/object.','Quotation survives as false but socially potent.','spoiler'),('ledger-key','Ch. 5 / Ch. 46','Tomas carries it throughout office; surrenders it directly to Osric.','Makes loss of office immediate and material.','Osric holds key.','spoiler')) as v(slug,first_use,custody,function,end_state,spoiler) on e.slug=v.slug
on conflict (entity_id) do update set book_code=excluded.book_code,first_major_use=excluded.first_major_use,custody_summary=excluded.custody_summary,narrative_function=excluded.narrative_function,end_state=excluded.end_state,spoiler_class=excluded.spoiler_class,metadata=excluded.metadata;

select o.id,h.id,'book-1',v.chapter,v.seq,v.action,v.notes,'governing','author_only' from (values
('harls-knife','harl',4,1,'held','Harl retains custody during early road work.'),('harls-knife','tam',17,2,'inherited','Tam receives Harl’s effects after Harl’s death and later controls the knife.'),('harls-knife','sela',46,3,'transferred','Tam gives the knife to Sela hilt-first before departure.'),('ledger-key','osric',46,1,'transferred','Tomas surrenders the Ledger key to Osric after refusing judgment.')) as v(object_slug,holder_slug,chapter,seq,action,notes) join public.lore_entities o on o.slug=v.object_slug join public.lore_entities h on h.slug=v.holder_slug;

on conflict (slug) do update set name=excluded.name,entity_type=excluded.entity_type,summary=excluded.summary,state=excluded.state,visibility=excluded.visibility;

select e.id,0,0,a.id,e.summary,'ratified constitutional fact','{"event_type":"constitutional_settlement","source":"Aurefold Constitution v1.9"}'::jsonb from public.lore_entities e join public.lore_entities a on a.slug='ash-fields' where e.slug='tenfold-compact-0-au'
on conflict (entity_id) do update set au_year=excluded.au_year,chronology_sort=excluded.chronology_sort,location_entity_id=excluded.location_entity_id,summary=excluded.summary,certainty=excluded.certainty,metadata=excluded.metadata;
select e.id,396,v.sort,l.id,e.summary,v.certainty,jsonb_build_object('event_type',v.event_type,'source','Book One v1.6 / Character & Knowledge Map v1.3') from public.lore_entities e join (values
('harl-road-death-396','death_and_rescue',150,'text-entered; route accounts remain contested','east-shoulder'),('lower-field-396','crowd_conflict',280,'text-entered; causal first aggressor unresolved','lower-field'),('gate-crisis-396','gate_crush',410,'text-entered; exact first aggressor and exclusive mechanics unresolved','bell-of-silence'),('ivet-death-396','death',420,'text-entered death; leaf mechanics multiply explainable','bell-of-silence'),('wren-divided-report-396','record_creation',440,'text-entered working record; not authoritative Chronicle truth','bell-of-silence'),('tomas-blank-page-396','institutional_refusal',460,'text-entered public action','bell-of-silence'),('sela-departure-east-396','departure',470,'locked Book One endpoint','east-shoulder')) as v(slug,event_type,sort,certainty,loc_slug) on e.slug=v.slug join public.lore_entities l on l.slug=v.loc_slug
on conflict (entity_id) do update set au_year=excluded.au_year,chronology_sort=excluded.chronology_sort,location_entity_id=excluded.location_entity_id,summary=excluded.summary,certainty=excluded.certainty,metadata=excluded.metadata;

select ev.id,p.id,v.role,v.notes,'governing','author_only' from (values
('harl-road-death-396','harl','dies','Death permanent; later accounts compete.'),('harl-road-death-396','sela','warns','Gives grounded terrain warning without prophetic claim.'),('lower-field-396','jeren-tesk','first_identifiable_bolt','First bolt Wren can identify; not a causal/moral first-aggressor answer.'),('lower-field-396','wren','observer','Builds bounded evidence from partial sequence.'),('lower-field-396','aren-lethren','command','Blocks pursuit.'),('lower-field-396','joric-vale','holds_wound_lane','Dies while holding a mixed wound lane.'),('gate-crisis-396','sela','witness','Partial elevated view; cannot own full mechanics.'),('gate-crisis-396','ivet','casualty','Fatally injured after helping clear a child.'),('ivet-death-396','ivet','dies','Death permanent.'),('ivet-death-396','sela','identifies','Names Ivet for record/washing work.'),('wren-divided-report-396','wren','author','Separates observations and source key.'),('tomas-blank-page-396','tomas','refuses_judgment','Ends test without entering classification.'),('tomas-blank-page-396','osric','receives_key','Receives Ledger key.'),('sela-departure-east-396','sela','departs','Leaves east with Harl’s knife.'),('sela-departure-east-396','alaine','does_not_call_back','Does not convert departure into order.')) as v(event_slug,participant_slug,role,notes) join public.lore_entities ev on ev.slug=v.event_slug join public.lore_entities p on p.slug=v.participant_slug
on conflict (event_entity_id,participant_entity_id,role) do update set notes=excluded.notes,state=excluded.state,visibility=excluded.visibility;

select ev.id,null,'Wren can identify Jeren Tesk as releasing the first bolt she can identify in the Lower Field sequence.','text-entered observation','bounded observation','lower-field-first-aggressor','governing','author_only','This does not establish who morally or causally began Lower Field.' from public.lore_entities ev where ev.slug='lower-field-396';
select ev.id,wh.id,'Whitehart can support nine received bodies in the Gate aftermath.','text-entered institutional count','defensible for received bodies','gate-casualty-count','governing','author_only','This is not the same measurement as the valley missing count.' from public.lore_entities ev join public.lore_entities wh on wh.slug='whitehart' where ev.slug='gate-crisis-396';
select ev.id,null,'Valley checks support twelve missing after the Gate crisis.','text-entered missing-person count','defensible for missing persons','gate-casualty-count','governing','author_only','The twelve missing must remain separate from the nine received bodies; no authoritative reconciliation is permitted.' from public.lore_entities ev where ev.slug='gate-crisis-396';

select a.id,b.id,v.rel,v.summary,null,null,'governing','author_only',jsonb_build_object('source',v.source) from (values
('sela','alaine','mentor_institutional','Alaine is shelter, authority and political danger in Sela’s Whitehart formation.','Book One Character & Knowledge Map v1.3'),('sela','harl','family_adjacent_mentor','Harl treats Sela through road work and practical judgment rather than reverence.','Book One v1.6'),('harl','tam','father_son','Harl is Tam’s father; work, tools and future plans pass through the relationship.','Book One manuscript'),('tomas','fen','tester_unclosed_mercy','Tomas’s prior unclosed mercy toward Fen becomes a central ethical wound.','Book One Character & Knowledge Map v1.3'),('perrin','wren','professional_methodological','Information appetite and evidentiary discipline overlap and conflict.','Book One v1.6 / Character Map v1.3'),('alaine','corven','kin_serenel','Alaine and Corven share the Serenel family connection; exact public presentation remains spoiler-controlled.','Book One v1.6'),('una','roan','former_lovers_close_friends','Former close friends and lovers; Roan insists love requires freedom to refuse while Una fears refusal can kill people under her responsibility.','Stormrider Civilization File v1.3 / Book Two control')) as v(a_slug,b_slug,rel,summary,source) join public.lore_entities a on a.slug=v.a_slug join public.lore_entities b on b.slug=v.b_slug;
