('whitehart-ledger','Whitehart Ledger','object','Whitehart institutional Ledger.','governing','public'),('burned-trial-note','Burned trial note','object','Temporary trial observation destroyed before judgment.','governing','author_only'),('perrin-commission','Perrin’s commission','object','Crown-watch commission governing Perrin’s Whitehart collection work.','governing','author_only'),('perrin-notebook','Perrin’s notebook','object','Perrin’s working notebook and self-entry record.','governing','author_only'),('sela-wire-bound-bowl','Sela’s wire-bound bowl','object','Ordinary family object repeatedly turned toward public meaning.','governing','author_only'),('harls-knife','Harl’s knife','object','Practical blade whose custody becomes a cross-book continuity control.','governing','author_only'),('sela-goat-counter','Sela’s goat counter','object','Old working counter later used among ration-horizon objects.','governing','author_only'),('merta-good-chair','Merta’s good chair','object','Ordinary chair carrying the material shape of waiting for Col.','governing','author_only'),('col-sleeve-coat','Col’s sleeve and coat','object','Material memory that cannot prove Col’s fate.','governing','author_only'),('east-shoulder-grave-material','East Shoulder grave material','object','Disturbed grave material with damaged provenance.','governing','author_only'),('bell-shod-beam','Bell and shod beam','object','Clapperless Bell and ordinary human-operated striking mechanism.','governing','public'),('harls-older-rope','Harl’s older rope','object','Rope selected for practical wet-knot/load behavior.','governing','author_only'),('wren-field-notes','Wren’s field notes','object','Measurements, source marks and divided-record working material.','governing','author_only'),('duskport-credit-papers','Duskport credit papers','object','Credit instruments funding material relief while preserving future leverage.','governing','author_only'),('iron-fittings-water-line','Iron fittings and water line','object','Infrastructure that saves lives while centralizing access and maintenance.','governing','author_only'),('signe-bright-cord','Signe’s bright cord','object','Planning cord that becomes lines, pegs and durable behavior.','governing','author_only'),('permanent-pegs','Permanent pegs','object','Temporary planning marks that become political facts.','governing','author_only'),('nine-ration-day-objects','Nine ration-day objects','object','Small material objects used to make scarcity bodily and hard to abstract.','governing','author_only'),('gate-leaves-hinges-bar','Gate leaves, hinges and bar','object','Gate architecture whose inward geometry remains a locked Book One fact.','governing','public'),('treatment-sheets-wrist-tags','Treatment sheets and wrist tags','object','Medical and identity records preserving distinct body/missing counts.','governing','author_only'),('ivet-wrist-tag','Ivet’s wrist tag','object','Name record carried through washing and burial work.','governing','author_only'),('joric-shield-spear','Joric’s store shield and spear','object','Borrowed weapons used while holding the mixed wound lane.','governing','author_only'),('nella-grain-carts','Nella’s grain carts','object','Relief grain staged before closure and delayed by the road.','governing','author_only'),('halla-grain-ticket','Halla’s grain ticket','object','Entered grain release preserving name, amount and future refusal terms.','governing','author_only'),('corrin-staff','Corrin’s staff','object','Staff broken during Tam’s assault.','governing','author_only'),('false-quotation-copies','False quotation copies','object','False wording whose copied carriers outlive attempts at correction.','governing','author_only'),('ledger-key','Ledger key','object','Office key surrendered by Tomas to Osric.','governing','author_only')
